# Generated by build.py from recipe.yml for recipe https-serve-with-a-self-signed-certificate. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--self-signed', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -k https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
